.lw-hero-copy, .lw-hero-galaxy { flex-direction: column; min-width: 0px; display: flex; }
.lw-hero-copy { align-items: flex-start; }
.lw-hero-copy > * { max-width: 100%; }
.lw-hero h1 { font-family: var(--sr-display); letter-spacing: -0.02em; color: var(--sr-ink); margin: 0px 0px 18px; font-size: clamp(28px, 3.6vw, 44px); line-height: 1.18; }
.lw-lead { color: var(--sr-blue-deep); margin: 0px 0px 14px; font-size: 16px; line-height: 1.7; }
.lw-body { color: var(--sr-ink-soft); margin: 0px 0px 14px; font-size: 15px; line-height: 1.75; }
.lw-outcome { border-left: 2px solid var(--sr-blue-tint); color: var(--sr-ink-soft); margin: 0px 0px 26px; padding-left: 15px; font-size: 14.5px; line-height: 1.75; }
.lw-hero-copy .lw-ctas { margin-top: auto; }
.lw-hero-galaxy-foot { justify-content: flex-end; align-items: center; gap: 16px; margin-top: 12px; display: flex; }
.lw-hero-galaxy-hint { color: var(--sr-ink-dim); margin: 0px; font-size: 12px; }
.lw-hero-galaxy-foot .lw-search { background: var(--sr-white); flex: 0 1 auto; }
.lw-hero-galaxy-foot .lw-search input { width: clamp(120px, 16vw, 190px); }
.lw-search { background: var(--sr-panel); border: 1px solid var(--sr-line); color: var(--sr-ink-dim); border-radius: 999px; align-items: center; gap: 8px; padding: 7px 14px; display: flex; position: relative; box-shadow: rgba(21, 32, 31, 0.08) 0px 2px 10px; }
.lw-search input { color: var(--sr-ink); background: 0px 0px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; outline: none; font-size: 13px; }
.lw-search input::placeholder { color: var(--sr-ink-dim); }
.lw-search-pop { background: var(--sr-white); border: 1px solid var(--sr-line); z-index: 20; border-radius: 10px; width: 300px; position: absolute; top: calc(100% + 8px); right: 0px; overflow: hidden; box-shadow: rgba(21, 32, 31, 0.16) 0px 10px 34px; }
.lw-search-pop button { width: 100%; color: var(--sr-ink); text-align: left; cursor: pointer; background: 0px 0px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; justify-content: space-between; align-items: center; gap: 10px; padding: 8px 13px; font-size: 13px; display: flex; }
.lw-search-pop button:hover { background: var(--sr-panel); }
.lw-search-pop i { border-radius: 50%; flex: 0 0 auto; width: 7px; height: 7px; }
.lw-search-pop i.math { background: var(--sr-green); }
.lw-search-pop i.physics { background: var(--sr-blue); }
.lw-galaxy-frame { background: rgb(5, 7, 15); border-radius: 16px; flex: 1 1 auto; min-height: 360px; position: relative; overflow: hidden; box-shadow: rgba(10, 25, 60, 0.28) 0px 16px 44px; }
.lw-galaxy-frame .sr-galaxy { aspect-ratio: auto; border-radius: 16px; height: 100%; min-height: 0px; }
.lw-galaxy-zoom { z-index: 4; flex-direction: column; gap: 8px; display: flex; position: absolute; bottom: 12px; right: 12px; }
.lw-galaxy-zoom.hidden { display: none; }
.lw-galaxy-zoom button { color: rgb(213, 222, 245); cursor: pointer; background: rgba(14, 22, 44, 0.82); border: 1px solid rgba(140, 165, 255, 0.3); border-radius: 8px; place-items: center; width: 32px; height: 32px; display: grid; }
.lw-galaxy-zoom button:hover { color: rgb(255, 255, 255); border-color: rgba(170, 195, 255, 0.6); }
.lw-galaxy-skeleton { background: rgb(5, 7, 15); border-radius: 16px; position: absolute; inset: 0px; overflow: hidden; }
.lw-galaxy-skeleton::before { content: ""; background: radial-gradient(circle at 28% 42%, rgba(255, 196, 107, 0.3) 0px, rgba(255, 196, 107, 0.3) 2px, rgba(0, 0, 0, 0) 3px), radial-gradient(circle at 34% 55%, rgba(255, 196, 107, 0.22) 0px, rgba(255, 196, 107, 0.22) 2px, rgba(0, 0, 0, 0) 3px), radial-gradient(circle at 22% 62%, rgba(255, 196, 107, 0.16) 0px, rgba(255, 196, 107, 0.16) 2px, rgba(0, 0, 0, 0) 3px), radial-gradient(circle at 66% 38%, rgba(107, 200, 255, 0.3) 0px, rgba(107, 200, 255, 0.3) 2px, rgba(0, 0, 0, 0) 3px), radial-gradient(circle at 74% 52%, rgba(107, 200, 255, 0.22) 0px, rgba(107, 200, 255, 0.22) 2px, rgba(0, 0, 0, 0) 3px), radial-gradient(circle at 60% 60%, rgba(107, 200, 255, 0.16) 0px, rgba(107, 200, 255, 0.16) 2px, rgba(0, 0, 0, 0) 3px); position: absolute; inset: 0px; }
.lw-galaxy-skeleton span { background: linear-gradient(100deg, rgba(0, 0, 0, 0) 20%, rgba(120, 150, 255, 0.14) 50%, rgba(0, 0, 0, 0) 80%) 0px 0px / 220% 100%; animation: 1.6s ease-in-out 0s infinite normal none running lw-shimmer; position: absolute; inset: 0px; }
@keyframes lw-shimmer { 
  0% { background-position: 130% 0px; }
  100% { background-position: -30% 0px; }
}
.lw-quote { text-align: center; border-top: 1px solid var(--sr-line); border-bottom: 1px solid var(--sr-line); max-width: 62ch; margin: 8px auto 0px; padding: 30px 0px 34px; }
.lw-quote p { color: var(--sr-blue-deep); margin: 0px 0px 10px; font-size: clamp(16px, 1.8vw, 20px); font-style: italic; line-height: 1.65; }
.lw-quote cite { color: var(--sr-ink-dim); font-size: 13px; font-style: normal; }
.lw-quote-title { color: var(--sr-ink-dim); margin-top: 2px; font-size: 12px; display: block; }
.lw-points { padding: 44px 0px 8px; }
.lw-points h2 { font-family: var(--sr-display); letter-spacing: -0.01em; color: var(--sr-ink); margin: 0px 0px 26px; font-size: clamp(20px, 2.2vw, 27px); }
.lw-points ol { grid-template-columns: repeat(4, minmax(0px, 1fr)); gap: 26px; margin: 0px; padding: 0px; list-style: none; display: grid; }
.lw-points li { border-top: 2px solid var(--sr-line); padding-top: 14px; }
.lw-point-n { letter-spacing: 0.1em; color: var(--sr-green-deep); margin-bottom: 8px; font-size: 12px; font-weight: 700; display: block; }
.lw-points p { color: var(--sr-ink-soft); margin: 0px; font-size: 14.5px; line-height: 1.65; }
.lw-cta { background: linear-gradient(120deg, var(--sr-green), var(--sr-blue)); color: var(--sr-white); text-align: center; border-radius: 22px; margin-top: 48px; padding: 42px clamp(20px, 4vw, 44px); box-shadow: rgba(14, 124, 155, 0.24) 0px 18px 50px; }
.lw-cta h2 { font-family: var(--sr-display); letter-spacing: -0.01em; margin: 0px 0px 22px; font-size: clamp(21px, 2.5vw, 30px); }
.lw-cta .lw-ctas { justify-content: center; }
.lw-cta .lw-btn.solid { background: var(--sr-white); color: var(--sr-blue-deep); box-shadow: rgba(21, 32, 31, 0.2) 0px 6px 18px; }
.lw-cta .lw-btn.solid:hover { background: var(--sr-panel); }
.lw-cta .lw-btn.ghost { color: var(--sr-white); background: rgba(255, 255, 255, 0.12); border-color: rgba(255, 255, 255, 0.5); }
@media (width <= 1100px) {
  .lw-nav-links, .lw-nav-actions { display: none; }
  .lw-burger { margin-left: auto; display: grid; }
  .lw-hero { grid-template-columns: 1fr; }
  .lw-hero-copy .lw-ctas { margin-top: 0px; }
  .lw-points ol { grid-template-columns: 1fr 1fr; }
}
@media (width <= 900px) {
  .lw-map { grid-template-columns: 1fr; height: 70vh; }
  .lw-map-books { border-right-width: medium; border-right-style: none; border-right-color: currentcolor; }
  .lw-map-detail { grid-template-columns: 1fr; }
  .lw-search { flex: 1 1 160px; }
  .lw-search input { width: 100%; min-width: 0px; }
}
@media (width <= 640px) {
  .lw-brand-name small { display: none; }
  .lw-points { padding-top: 32px; }
  .lw-points ol { grid-template-columns: 1fr; gap: 18px; }
  .lw-cta { padding: 32px 18px; }
  .lw-galaxy-frame { min-height: 300px; }
}
@media (width <= 380px) {
  .lw-content, .lw-nav-inner { padding-left: 12px; padding-right: 12px; }
}
.sr-print-lesson { display: none; }
@page { size: a4; margin: 14mm 13mm 16mm; }
@media print {
  html, body { background: var(--sr-white); width: auto; height: auto; overflow: visible; }
  body { print-color-adjust: exact; }
  .sr-app, .sr-app.mobile { width: auto; height: auto; min-height: 0px; display: block; position: static; inset: auto; overflow: visible; transform: none; }
  .sr-catalog, .sr-scrim, .sr-langmenu, .sr-d-top, .sr-d-scroll { display: none !important; }
  .sr-detail { min-width: 0px; min-height: 0px; display: block; overflow: visible; }
  .sr-print-lesson { --sr-font: "Arial Unicode MS", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", "Noto Sans SC", sans-serif; --sr-display: var(--sr-font); --sr-body: var(--sr-font); max-width: 100%; color: var(--sr-ink); font-family: var(--sr-body); font-size: 11pt; line-height: 1.55; display: block; }
  .sr-print-trail { color: var(--sr-ink-dim); margin: 0px 0px 4mm; font-size: 8.5pt; font-weight: 600; }
  .sr-print-title { color: var(--sr-ink); font-family: var(--sr-display); margin: 0px; font-size: 20pt; line-height: 1.25; }
  .sr-print-title .sr-num { color: var(--sr-blue); }
  .sr-print-section { margin-top: 8mm; }
  .sr-print-section-title { border-bottom: 1px solid var(--sr-line); color: var(--sr-ink); font-family: var(--sr-display); margin: 0px 0px 4mm; padding-bottom: 2mm; font-size: 14pt; line-height: 1.3; }
  .sr-print-lesson .sr-read, .sr-print-lesson .sr-ex-list { margin-top: 0px; }
  .sr-print-lesson .sr-read-fig, .sr-print-lesson .sr-compact-figure, .sr-print-lesson .sr-ex, .sr-print-lesson .sr-ex-fig { break-inside: avoid; }
  .sr-print-lesson .sr-read-fig img, .sr-print-lesson .sr-read-fig svg, .sr-print-lesson .sr-ex-fig img, .sr-print-lesson .sr-ex-fig svg { max-width: 100%; height: auto; }
  .sr-print-lesson .sr-ex-body > div:first-child, .sr-print-lesson .sr-read-fig[data-figure-layout="scroll"], .sr-print-lesson .sr-ex-fig[data-figure-layout="scroll"] { overflow: visible; }
  .sr-print-lesson .sr-figure-media { --ld-figure-ink: var(--sr-ink); --ld-figure-muted: var(--sr-ink-soft); --ld-figure-accent: var(--sr-ink); --ld-figure-accent-soft: var(--sr-ink-dim); --ld-figure-grid: var(--sr-line); }
  .sr-print-lesson [data-figure-layout="scroll"] .sr-figure-media { width: 100%; max-width: 100%; }
}
